fun minEatingSpeed(piles: IntArray, h: Int): Int {
    // hours needed at speed k — ceil division without floating point
    fun hoursAt(k: Int): Long =
        piles.sumOf { pile -> ((pile + k - 1) / k).toLong() }

    var low = 1
    var high = piles.max()

    while (low < high) {
        val mid = low + (high - low) / 2      // avoids overflow vs (low + high) / 2
        if (hoursAt(mid) <= h) {
            high = mid                         // mid works; it may still be beatable
        } else {
            low = mid + 1                      // too slow
        }
    }
    return low                                 // low == high == smallest workable speed
}

