import java.util.PriorityQueue

fun topKFrequent(nums: IntArray, k: Int): IntArray {
    val counts = nums.toList().groupingBy { it }.eachCount()

    // Min-heap on frequency: the smallest frequency sits on top and gets evicted
    val heap = PriorityQueue<Map.Entry<Int, Int>>(compareBy { it.value })
    for (entry in counts.entries) {
        heap.offer(entry)
        if (heap.size > k) heap.poll()
    }
    return heap.map { it.key }.toIntArray()
}

fun topKFrequentBuckets(nums: IntArray, k: Int): IntArray {
    val counts = nums.toList().groupingBy { it }.eachCount()

    // A value can appear at most nums.size times, so frequency is a bounded index
    val buckets = Array(nums.size + 1) { mutableListOf<Int>() }
    for ((value, freq) in counts) buckets[freq].add(value)

    val result = ArrayList<Int>(k)
    for (freq in buckets.indices.reversed()) {
        for (value in buckets[freq]) {
            result.add(value)
            if (result.size == k) return result.toIntArray()
        }
    }
    return result.toIntArray()
}

