fun canFinish(numCourses: Int, prerequisites: Array<IntArray>): Boolean {
    val graph = Array(numCourses) { mutableListOf<Int>() }
    val inDegree = IntArray(numCourses)

    for ((course, prereq) in prerequisites.map { it[0] to it[1] }) {
        graph[prereq].add(course)      // edge prereq -> course
        inDegree[course]++
    }

    val queue = ArrayDeque<Int>()
    for (c in 0 until numCourses) if (inDegree[c] == 0) queue.add(c)

    val order = mutableListOf<Int>()   // the follow-up answer, free
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        order.add(node)
        for (next in graph[node]) {
            if (--inDegree[next] == 0) queue.add(next)
        }
    }
    return order.size == numCourses    // shortfall => a cycle blocked the rest
}

