// 1. Subsets — power set
fun subsets(nums: IntArray): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val current = mutableListOf<Int>()

    fun backtrack(start: Int) {
        result.add(current.toList())          // every node is a valid subset
        for (i in start until nums.size) {
            current.add(nums[i])              // choose
            backtrack(i + 1)                  // explore (i+1 => no reuse)
            current.removeAt(current.lastIndex)  // un-choose
        }
    }
    backtrack(0)
    return result
}

// 2. Combination Sum — unlimited reuse
fun combinationSum(candidates: IntArray, target: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val current = mutableListOf<Int>()
    candidates.sort()                          // enables the early break

    fun backtrack(start: Int, remaining: Int) {
        if (remaining == 0) { result.add(current.toList()); return }

        for (i in start until candidates.size) {
            if (candidates[i] > remaining) break    // sorted: everything after is worse
            current.add(candidates[i])             // choose
            backtrack(i, remaining - candidates[i]) // explore — `i`, not `i + 1`, allows reuse
            current.removeAt(current.lastIndex)     // un-choose
        }
    }
    backtrack(0, target)
    return result
}

