class ListNode(var v: Int) { var next: ListNode? = null }

// 1. Reverse — O(n) time, O(1) space
fun reverse(head: ListNode?): ListNode? {
    var prev: ListNode? = null
    var current = head
    while (current != null) {
        val next = current.next     // save BEFORE overwriting
        current.next = prev
        prev = current
        current = next
    }
    return prev
}

// 2. Cycle detection + entry point (Floyd)
fun detectCycle(head: ListNode?): ListNode? {
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
        if (slow === fast) {                 // reference equality, not ==
            var entry = head
            while (entry !== slow) {
                entry = entry?.next
                slow = slow?.next
            }
            return entry
        }
    }
    return null
}

// 3. Middle node — for even length this returns the second middle
fun middle(head: ListNode?): ListNode? {
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
    }
    return slow
}

